const D = { density:.55, energy:.55, hue:210, speed:1, scale:1, x:.5, y:.5, settle:.5, blur:.5, style:'snow', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u=Math.min(width,height);
if(!S.spr){ const R=48; const s=createGraphics(R*2,R*2); s.pixelDensity(1); s.noStroke();
  for(let r=R;r>0;r--){ const a=Math.pow(1-r/R,1.8)*255; s.fill(255,255,255,a); s.ellipse(R,R,r*2,r*2); }
  S.spr=s; }
if(S.seedUsed!==P.seed){ S.seedUsed=P.seed;
  const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453; return s-Math.floor(s);};
  S.hoff=fr(1);
  S.fl=[]; for(let k=0;k<260;k++) S.fl.push([fr(k*4+2),fr(k*4+3),fr(k*4+4),fr(k*4+5)]);
}
const cx=P.x*width, cy=P.y*height, R=u*0.46*P.scale;

// perpetual re-agitation: swirl strength never fully decays (long incommensurate re-shake)
const shake=0.55+0.45*Math.sin(K.t*0.13)+0.25*Math.sin(K.t*0.31+1.1)+A.bass*0.6;
const swirl=(0.5+P.energy*1.1)*Math.max(0.2,shake);
const t=K.t;
const style=P.style;
// water fill tint
const water = style==='glitter_gold'?[40,55]: style==='confetti'?[280,30]: style==='ink'?[0,0]:[205,45];

// --- globe water fill (broad area element) ---
push(); blendMode(ADD); noStroke();
const wf=0.10+0.09*(0.5+0.5*Math.sin(t*0.4))+K.intensity*0.05;
for(let ring=0;ring<5;ring++){ const rr=R*(1-ring*0.16);
  fill(water[0], water[1]*0.6, 100, (style==='ink'?4:9)*wf*(1+ring*0.3));
  ellipse(cx+ R*0.05*Math.sin(t*0.5), cy - R*0.06*Math.cos(t*0.37), rr*2, rr*2);
}
// central highlight (light through the glass)
fill(0,0,100, 10*wf); ellipse(cx-R*0.28, cy-R*0.3, R*0.7, R*0.7);
blendMode(BLEND); pop();

// --- swirling flakes, clipped to the globe ---
const nf=Math.round(70+P.density*180);
push();
drawingContext.save();
drawingContext.beginPath(); drawingContext.arc(cx,cy,R,0,Math.PI*2); drawingContext.clip();
blendMode(ADD); imageMode(CENTER); noStroke();
for(let k=0;k<nf;k++){ const f=S.fl[k];
  const depth=f[3];                             // 0 far .. 1 near
  const baseR=(0.15+f[0]*0.85)*R;
  // vortex: angular speed higher near center, settling sink adds downward drift
  const ang=f[1]*6.28 + swirl*t*(0.5+ (1-baseR/R)*0.9)*(0.6+depth*0.8) + f[2]*2;
  const sink=(0.2+P.settle*0.8);
  const rr=baseR*(0.7+0.3*Math.sin(t*0.6*swirl+f[1]*6.28));
  let X=cx + Math.cos(ang)*rr;
  let Y0=Math.sin(ang)*rr + Math.sin(t*0.3+f[1]*6.28)*R*0.05 + (t*sink*20*(0.3+depth));
  let dy=(((Y0+R)%(2*R))+2*R)%(2*R);            // wrap within globe vertically
  let Y=cy + dy - R;
  const sz=u*(0.006+depth*0.016)*P.scale*(1+P.blur*depth*1.4);
  const br=0.45+depth*0.55;
  let hh=P.hue, ss=0;
  if(style==='glitter_gold'){ hh=(42+f[2]*20)%360; ss=45+depth*20; }
  else if(style==='confetti'){ hh=(f[2]*360); ss=70; }
  else if(style==='ink'){ hh=0; ss=0; }
  const a=(0.5+0.5*Math.sin(t*3+f[2]*20))*br*(0.6+P.energy*0.6);
  if(style==='ink'){ tint(0,0,100, Math.min(100,70*a)); }
  else { tint(0,0,100, Math.min(100,26*a)); image(S.spr,X,Y,sz*2.6,sz*2.6); tint(hh,ss,100, Math.min(100,80*a)); }
  image(S.spr,X,Y,sz,sz);
}
imageMode(CORNER); blendMode(BLEND);
drawingContext.restore();
// glass vignette rim
noFill(); strokeWeight(u*0.012);
for(let s=0;s<4;s++){ stroke(water[0], 20, 100, 8-s*1.5); ellipse(cx,cy,(R+ s*u*0.01)*2,(R+ s*u*0.01)*2); }
pop();
